        }

        @Override
        public FilterResult tail(Node node, int depth) {
            return ("b".equals(node.nodeName())) ? FilterResult.REMOVE : FilterResult.CONTINUE;
        }
    }, doc.select("div"));
    assertEquals("<div></div>\n<div>\n There be\n</div>", doc.select("body").html());
}

