@Test public void canAddChildren_1_oe() {
    Document doc = Jsoup.parse("<div><p></p><p></p></div>");

    NodeTraversor.traverse(new NodeVisitor() {
        int i = 0;
        @Override
        public void head(Node node, int depth) {
            if (node.nodeName().equals("p")) {
                Element p = (Element) node;
                p.append("<span>" + i++ + "</span>");
            }
        }

        @Override
        public void tail(Node node, int depth) {
            if (node.nodeName().equals("p")) {
                Element p = (Element) node;
                p.append("<span>" + i++ + "</span>");
            }
        }
    }, doc);

    assertEquals("<div>\n" + " <p><span>0</span><span>1</span></p>\n" + " <p><span>2</span><span>3</span></p>\n" + "</div>",doc.body().html());
    }

focal_method:
public Element body() {
        Element html = htmlEl();
        for (Element el: html.childElementsList()) {
            if ("body".equals(el.normalName()) || "frameset".equals(el.normalName()))
                return el;
        }
        return html.appendElement("body");
    }

