@Test public void eachAttr_1_oe() {
    Document doc = Jsoup.parse(
        "<div><a href='/foo'>1</a><a href='http://example.com/bar'>2</a><a href=''>3</a><a>4</a>",
        "http://example.com");

    List<String> hrefAttrs = doc.select("a").eachAttr("href");
    assertEquals(3, hrefAttrs.size());
    }

