@Test public void chompBalancedMatchesAsMuchAsPossible_1_oe() {
    TokenQueue tq = new TokenQueue("unbalanced(something(or another)) else");
    tq.consumeTo("(");
    String match = tq.chompBalanced('(', ')');
    assertEquals("something(or another)", match);
