@Test
void isAscii_1_oe() {
    assertTrue(StringUtil.isAscii(""));
}

focal_method:
public static boolean isAscii(String string) {
        Validate.notNull(string);
        for (int i = 0; i < string.length(); i++) {
            int c = string.charAt(i);
            if (c > 127) { // ascii range
                return false;
            }
        }
        return true;
    }

