        .add("Key2", "Val2")
        .add("Key3", null);

    Attributes three = new Attributes()
        .add("Key2", "Val2")
        .add("Key3", null)
        .add("Key1", "Val1");

    Attributes four = new Attributes()
        .add("Key1", "Val1")
        .add("Key2", "Val2")
        .add("Key3", null)
        .add("Key4", "Val4");

    assertEquals(one, one.clone());
    }

