        assertEquals("<html>
 <head>
  <title>Format test</title>
 </head>
 <body>
  <div>
   <p>Hello <span>jsoup <span>users</span></span></p>
   <p>Good.</p>
  </div>
 </body>
</html>", doc.html());
    }

