@Test void tracksPosition_22_oe() {
    String html = "<p id=1\n class=foo>\n<span>Hello\n &reg;\n there &copy.</span> now.\n <!-- comment --> ";
    Document doc = Jsoup.parse(html, TrackingParser);

    Element body = doc.expectFirst("body");
